        let body_start = meta_size;
        let body_end = message_size - attachment_size;
        let body = payload[body_start..body_end].to_vec();
        let attachment = payload[body_end..].to_vec();

        Ok(Self {
            meta,
            body,
            attachment,
        })
    }
